import{a as e,c as t,i as n,l as r,o as i,s as a}from"./useSeo-BLOl_5vs.js";var o={name:`Dn. Rimsha Naseer`,role:`Certified Clinical Nutritionist`,mission:`To make evidence-based nutrition simple, sustainable, and personalized for every lifestyle across the globe.`,story:`After helping family members reverse lifestyle disorders through structured food therapy, I turned my clinical background into a remote-first nutrition practice. Today, I coach clients in 14+ countries with plans built for real work schedules, travel, and medical needs.`,philosophy:`No crash diets. No guesswork. Every protocol combines clinical insight, habit psychology, and practical meals your routine can actually sustain.`,experience:`9+ years`},s=[`M.Sc. Clinical Nutrition`,`Certified Diabetes Educator`,`PCOS & Hormonal Health Specialist`,`Sports Nutrition Foundation Credential`],c=[{id:`tb1`,label:`Clinical & Certified`,subtitle:`Globally recognized credentials`},{id:`tb2`,label:`1,800+ Clients Coached`,subtitle:`Across 14 countries`},{id:`tb3`,label:`Evidence-Based Plans`,subtitle:`Nutrition science first`},{id:`tb4`,label:`Remote Friendly`,subtitle:`100% online consultation model`}],l=[{id:`st1`,label:`Average Fat Loss in 12 Weeks`,value:`6.8 kg`},{id:`st2`,label:`Client Retention Rate`,value:`89%`},{id:`st3`,label:`Improved Blood Markers`,value:`92%`}],u=[{id:`srv1`,title:`Weight Loss Accelerator`,summary:`Structured fat-loss roadmap for busy professionals with weekly accountability, appetite control, and flexible meals that survive real life.`,features:[`Metabolic and routine assessment`,`Protein, fiber and portion targets`,`Weekly progress and plateau review`,`Travel-friendly meal swaps`,`Craving and weekend strategy`],priceFrom:`$149`,ctaText:`Start Weight Loss Plan`},{id:`srv2`,title:`Medical Nutrition Therapy`,summary:`Condition-specific planning for PCOS, diabetes, thyroid, gut and inflammatory concerns with symptom-aware food structure.`,features:[`Clinical symptom tracker`,`Lab-aware nutrition adjustments`,`Medication-food timing support`,`Insulin and inflammation strategy`,`Doctor-friendly progress notes`],priceFrom:`$189`,ctaText:`Get Clinical Guidance`},{id:`srv3`,title:`Custom Diet Blueprint`,summary:`Personalized meal architecture aligned with your culture, schedule, budget, food preferences, family meals and cooking energy.`,features:[`Macro-personalized menu`,`Grocery and recipe packs`,`Habit reset framework`,`Dining-out decision guide`,`Family meal adaptation`],priceFrom:`$119`,ctaText:`Build My Plan`}],d=[{id:`pr1`,name:`Starter Reset`,price:`$99`,billing:`one-time`,description:`Ideal for first-time clients needing a clear action plan before committing to coaching.`,features:[`1 consultation (45 min)`,`14-day meal structure`,`Goal and barrier audit`,`Email support for 7 days`,`Simple grocery starter list`],highlighted:!1,scarcity:`Only 12 slots this month`,ctaText:`Book Starter Reset`},{id:`pr2`,name:`Transformation Plus`,price:`$249`,billing:`monthly`,description:`Most popular package for sustainable fat loss, habit coaching and measurable routine change.`,features:[`4 consultations per month`,`Weekly plan revisions`,`WhatsApp accountability`,`Progress dashboard review`,`Plateau and craving fixes`],highlighted:!0,scarcity:`Limited to 20 active clients`,ctaText:`Choose Transformation Plus`},{id:`pr3`,name:`Clinical Care Pro`,price:`$359`,billing:`monthly`,description:`For medical conditions requiring close monitoring, nutrition therapy and higher-touch guidance.`,features:[`Bi-weekly deep reviews`,`Lab report interpretation`,`Priority messaging support`,`Symptom and medication timing log`,`Clinical nutrition progress summary`],highlighted:!1,scarcity:`High-touch care, limited onboarding`,ctaText:`Apply for Clinical Care`}],f=[{id:`tr1`,name:`Nora, 34`,timeline:`14 weeks`,focus:`Postpartum fat loss`,beforeMetric:`Body Fat: 38%`,afterMetric:`Body Fat: 29%`,image:`https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=900&q=80`},{id:`tr2`,name:`Ethan, 41`,timeline:`16 weeks`,focus:`Type 2 diabetes management`,beforeMetric:`HbA1c: 8.2`,afterMetric:`HbA1c: 6.4`,image:`https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=900&q=80`},{id:`tr3`,name:`Mina, 29`,timeline:`12 weeks`,focus:`PCOS symptom relief`,beforeMetric:`Cycle Irregularity: high`,afterMetric:`Cycle Regularity: stable`,image:`https://images.unsplash.com/photo-1488426862026-3ee34a7d66df?auto=format&fit=crop&w=900&q=80`}],p=[{id:`ts1`,name:`Hannah K.`,location:`Toronto, Canada`,rating:5,goal:`Lose 10 kg after desk-job burnout`,result:`Lost 11.2 kg in 5 months and improved energy`,quote:`I finally stopped dieting in cycles. The plan felt realistic, and weekly check-ins kept me consistent.`,beforeLabel:`Before: constant cravings`,afterLabel:`After: stable appetite + confidence`,image:`https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=600&q=80`},{id:`ts2`,name:`Karim D.`,location:`Dubai, UAE`,rating:5,goal:`Control blood sugar naturally`,result:`Reduced fasting glucose by 24%`,quote:`Clear food timing and smart carb strategy changed my numbers without feeling deprived.`,beforeLabel:`Before: glucose spikes`,afterLabel:`After: smoother daily readings`,image:`https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=600&q=80`},{id:`ts3`,name:`Sofia R.`,location:`Madrid, Spain`,rating:5,goal:`Fix gut issues and bloating`,result:`Bloating episodes dropped by 80%`,quote:`The phased gut protocol worked better than anything I tried before. My sleep improved too.`,beforeLabel:`Before: daily discomfort`,afterLabel:`After: better digestion + sleep`,image:`https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=600&q=80`},{id:`ts4`,name:`Ayesha M.`,location:`Lahore, Pakistan`,rating:5,goal:`Manage PCOS cravings with family meals`,result:`Cycle tracking improved and cravings reduced`,quote:`I did not need a separate diet from my family. The swaps worked with our usual food and made consistency possible.`,beforeLabel:`Before: intense evening cravings`,afterLabel:`After: calmer appetite rhythm`,image:`https://images.unsplash.com/photo-1534751516642-a1af1ef26a56?auto=format&fit=crop&w=600&q=80`},{id:`ts5`,name:`Emily W.`,location:`London, UK`,rating:5,goal:`Rebuild energy after stress weight gain`,result:`Lost 7.4 kg and felt steady through workdays`,quote:`The best part was how normal it felt. I could eat out, work late, and still know what to do the next day.`,beforeLabel:`Before: skipped meals + fatigue`,afterLabel:`After: steady meals + energy`,image:`https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=600&q=80`},{id:`ts6`,name:`Omar S.`,location:`Doha, Qatar`,rating:5,goal:`Improve cholesterol and waist measurement`,result:`Waist down 9 cm with better lipid habits`,quote:`I understood my portions for the first time. The plan was practical enough for business lunches and travel weeks.`,beforeLabel:`Before: random portions`,afterLabel:`After: controlled plates + routine`,image:`https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=600&q=80`}],m=[{id:`fq1`,question:`Do you provide fully online consultations?`,answer:`Yes. Every session is conducted online with shared plans, progress tracking, and follow-up support.`},{id:`fq2`,question:`Can you help with PCOS, diabetes, or thyroid issues?`,answer:`Absolutely. Clinical nutrition therapy is tailored to your condition, medication schedule, and biomarkers.`},{id:`fq3`,question:`How soon can I start?`,answer:`Most clients begin within 3 to 5 days. Priority onboarding is available based on active slot capacity.`},{id:`fq4`,question:`How much does online nutrition coaching cost?`,answer:`Plans start from $119, depending on your goals and the length of support you need. Every plan includes a personalized nutrition plan and ongoing check-ins.`},{id:`fq5`,question:`What happens after I book a consultation?`,answer:`You share your health background and goals, then receive a personalized nutrition blueprint built around your body, routine, and preferences, followed by weekly check-ins to track progress.`},{id:`fq6`,question:`Do I need to visit in person?`,answer:`No. Dietrix Fit is a 100% remote practice — consultations, plans, and check-ins all happen online, so you can work with a certified nutritionist from anywhere in the world.`},{id:`fq7`,question:`How does ongoing support work after I get my plan?`,answer:`You get weekly check-ins and plan adjustments based on your progress, with continuous support until you hit your target.`},{id:`fq8`,question:`Can I book a consultation from outside Pakistan?`,answer:`Yes. Dietrix Fit coaches clients across 14+ countries, including the USA, UK, Canada, Germany, France, Saudi Arabia, the UAE, and Australia, entirely online.`}],h=[{slug:`best-high-protein-breakfast-for-fat-loss`,title:`Best High-Protein Breakfast Ideas for Sustainable Fat Loss`,seoTitle:`High-Protein Breakfast for Weight Loss | Dietrix Fit`,seoDescription:`Discover high-protein breakfast ideas that improve fullness, reduce cravings, and support sustainable weight loss without crash dieting or meal stress.`,category:`Weight Loss`,excerpt:`A strategic breakfast can reduce evening cravings and improve total daily calorie control. Here is how to design one.`,publishedAt:`2026-03-11`,readTime:`7 min read`,heroImage:`https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=1200&q=80`,sections:[{heading:`Why Protein in the Morning Matters`,paragraphs:[`Morning protein intake increases satiety hormones and helps reduce snacking later in the day. For professionals with long work hours, this is one of the easiest behavior upgrades.`,`Aim for 25 to 35 grams of protein in your first meal. This can come from eggs, Greek yogurt, tofu, cottage cheese, or quality protein blends paired with fiber-rich foods.`]},{heading:`Build a Balanced Plate`,subheading:`Use the 3-part formula`,paragraphs:[`Combine lean protein, slow carbohydrates, and healthy fat. Example: spinach omelet + seeded toast + avocado slices.`,`Keep preparation simple. Repetition beats complexity when your goal is consistency over the next 12 weeks.`]},{heading:`Common Mistakes to Avoid`,paragraphs:[`Avoid ultra-processed breakfast bars marketed as healthy. Most are low in protein and high in sugar alcohols that can trigger hunger rebounds.`,`If your appetite is low in the morning, start with a lighter protein smoothie and scale up over 1 to 2 weeks.`]},{heading:`High-Protein Breakfast Templates`,subheading:`Use repeatable meals instead of daily guesswork`,paragraphs:[`A strong breakfast template includes one protein anchor, one fiber source, one colorful plant food, and one satisfaction element such as avocado, olive oil, nuts, or seeds.`,`Examples include Greek yogurt with berries and chia, eggs with vegetables and seeded toast, tofu scramble with beans, or a protein smoothie paired with fruit and nuts.`]},{heading:`How to Adjust for Fat Loss`,paragraphs:[`For fat loss, keep the protein stable and adjust energy through portions of fats and carbohydrates. This preserves fullness while giving the body a controlled calorie signal.`,`Track afternoon hunger, evening cravings, and workout energy for two weeks. These signals often show whether breakfast needs more fiber, more protein, or a lighter portion.`]}],articleFaqs:[{id:`best-high-protein-breakfast-for-fat-loss-faq-1`,question:`How much protein should I eat at breakfast for fat loss?`,answer:`Aim for 25 to 35 grams from sources like eggs, Greek yogurt, tofu, cottage cheese, or a quality protein blend, paired with fiber-rich foods.`},{id:`best-high-protein-breakfast-for-fat-loss-faq-2`,question:`What foods should I avoid for a high-protein breakfast?`,answer:`Avoid ultra-processed breakfast bars marketed as healthy — most are low in protein and high in sugar alcohols that can trigger hunger rebounds later in the day.`},{id:`best-high-protein-breakfast-for-fat-loss-faq-3`,question:`What if I have low appetite in the morning?`,answer:`Start with a lighter protein smoothie and scale up the portion over 1 to 2 weeks rather than forcing a full plate immediately.`}],internalLinks:[{label:`Explore our weight loss services`,to:`/services`},{label:`Book a 1-on-1 consultation`,to:`/booking`}]},{slug:`pcos-diet-plan-basics-that-actually-work`,title:`PCOS Diet Plan Basics That Actually Work for Hormonal Balance`,seoTitle:`PCOS Diet Plan Online | Nutrition Coaching`,seoDescription:`Learn PCOS diet plan basics with meal timing, insulin-friendly foods, protein, fiber, and habit strategies for hormonal balance and cravings naturally.`,category:`Health Conditions`,excerpt:`PCOS nutrition is not about extreme restriction. It is about insulin-aware structure, anti-inflammatory foods, and stress management.`,publishedAt:`2026-02-25`,readTime:`9 min read`,heroImage:`https://images.unsplash.com/photo-1498837167922-ddd27525d352?auto=format&fit=crop&w=1200&q=80`,sections:[{heading:`Start With Insulin Stability`,paragraphs:[`Many PCOS symptoms are intensified by insulin resistance. Build meals that combine protein, fiber, and controlled carbohydrate portions.`,`Spacing meals 3 to 4 hours apart helps avoid repetitive grazing and supports a clearer hunger rhythm.`]},{heading:`Nutrients That Support Hormonal Health`,subheading:`Focus on quality first`,paragraphs:[`Magnesium-rich foods, omega-3 sources, and zinc-containing meals can support hormonal pathways and inflammation control.`,`Consistency for at least 8 to 12 weeks is essential before evaluating progress.`]},{heading:`Lifestyle Multipliers`,paragraphs:[`Sleep regularity and strength training are major multipliers for PCOS outcomes. Nutrition alone is powerful, but paired interventions perform better.`,`Track cycle length, energy, and cravings weekly to observe meaningful trend changes.`]},{heading:`Build an Insulin-Friendly Plate`,subheading:`Make every meal easier to repeat`,paragraphs:[`Start with protein, add high-fiber vegetables, choose a controlled portion of slow carbohydrate, then include a small amount of healthy fat for satisfaction.`,`This structure helps reduce glucose swings and makes meals easier to adapt across Pakistani, Middle Eastern, European, or North American food routines.`]},{heading:`What to Track for Better Decisions`,paragraphs:[`PCOS progress is not measured by weight alone. Track cravings, energy dips, cycle length, acne changes, sleep quality, waist measurement, and lab markers when available.`,`A weekly review makes the plan feel less emotional. Instead of guessing whether the diet is working, you can adjust meals based on real patterns.`]}],articleFaqs:[{id:`pcos-diet-plan-basics-that-actually-work-faq-1`,question:`How often should I eat with PCOS?`,answer:`Space meals 3 to 4 hours apart to avoid repetitive grazing and support a clearer hunger rhythm, building each plate around protein, fiber, and controlled carbohydrate portions.`},{id:`pcos-diet-plan-basics-that-actually-work-faq-2`,question:`How long before a PCOS diet plan shows results?`,answer:`Consistency for at least 8 to 12 weeks is essential before evaluating progress — track cycle length, energy, and cravings weekly to spot real trends.`},{id:`pcos-diet-plan-basics-that-actually-work-faq-3`,question:`Does nutrition alone manage PCOS symptoms?`,answer:`Nutrition is powerful, but sleep regularity and strength training are major multipliers — paired interventions consistently outperform diet changes alone.`}],internalLinks:[{label:`See our medical nutrition therapy program`,to:`/services`},{label:`Speak with our nutritionist`,to:`/contact`}]},{slug:`simple-weekly-diet-planning-for-busy-professionals`,title:`Simple Weekly Diet Planning Framework for Busy Professionals`,seoTitle:`Weekly Diet Planning for Busy Professionals`,seoDescription:`Use a realistic weekly diet planning system for busy professionals who want healthy eating without spending hours in the kitchen every week at home.`,category:`Diet Plans`,excerpt:`This 60-minute weekly planning method reduces food decisions and keeps you aligned with your health goals.`,publishedAt:`2026-01-30`,readTime:`6 min read`,heroImage:`https://images.unsplash.com/photo-1467453678174-768ec283a940?auto=format&fit=crop&w=1200&q=80`,sections:[{heading:`The 60-Minute Planning Sprint`,paragraphs:[`Use one session weekly to define your protein anchors, grocery list, and fallback meals for high-stress days.`,`When time is limited, a good-enough plan outperforms a perfect plan that never gets implemented.`]},{heading:`Create Decision-Light Meals`,subheading:`Reduce friction during weekdays`,paragraphs:[`Choose two breakfast options, two lunch options, and three dinner templates. Rotate rather than reinvent.`,`Batch prep one protein and one fiber-rich carb source to simplify execution.`]},{heading:`Build Your Emergency Nutrition Kit`,paragraphs:[`Keep quick options at work and while traveling: nuts, protein sachets, fruit, and low-sugar yogurt.`,`Your environment should support your goals even on chaotic days.`]},{heading:`Design a Flexible Grocery System`,subheading:`Shop by meal roles, not random recipes`,paragraphs:[`Choose two proteins, two fiber-rich carbohydrates, three vegetables, two fruits, and two flavor builders each week. This keeps variety high without making planning exhausting.`,`When groceries have clear roles, you can build plates quickly even when the exact recipe changes.`]},{heading:`Plan for Weekends Before They Happen`,paragraphs:[`Most busy professionals do well Monday to Thursday and lose structure on weekends. Decide your restaurant strategy, hydration target, and protein anchors before Friday arrives.`,`The goal is not to avoid social meals. The goal is to keep enough rhythm that one relaxed meal does not become three chaotic days.`]}],articleFaqs:[{id:`simple-weekly-diet-planning-for-busy-professionals-faq-1`,question:`How much time does weekly diet planning actually take?`,answer:`A single 60-minute weekly session to define protein anchors, a grocery list, and fallback meals for high-stress days is enough to stay consistent.`},{id:`simple-weekly-diet-planning-for-busy-professionals-faq-2`,question:`How many meal options do I need to plan?`,answer:`Two breakfast options, two lunch options, and three dinner templates rotated through the week are enough to reduce decision fatigue without feeling repetitive.`},{id:`simple-weekly-diet-planning-for-busy-professionals-faq-3`,question:`How do I stay on track over weekends?`,answer:`Decide your restaurant strategy, hydration target, and protein anchors before Friday arrives, so one relaxed meal doesn't turn into three chaotic days.`}],internalLinks:[{label:`View custom diet blueprint service`,to:`/services`},{label:`Reserve a planning consultation`,to:`/booking`}]},{slug:`diabetes-friendly-plate-method-for-busy-families`,title:`Diabetes-Friendly Plate Method for Busy Families`,seoTitle:`Diabetes-Friendly Plate Method | Online Nutritionist`,seoDescription:`Learn a diabetes-friendly plate method for family meals, blood sugar stability, portion control, and easier weekly nutrition decisions at home safely.`,category:`Health Conditions`,excerpt:`Blood sugar support becomes easier when meals follow a repeatable plate structure instead of strict food fear.`,publishedAt:`2026-03-28`,readTime:`8 min read`,heroImage:`https://images.unsplash.com/photo-1490645935967-10de6ba17061?auto=format&fit=crop&w=1200&q=80`,sections:[{heading:`Start With Meal Architecture`,paragraphs:[`A diabetes-friendly plate usually starts with non-starchy vegetables, adds lean protein, includes a measured slow carbohydrate, and finishes with a healthy fat or flavor element.`,`This structure lowers decision fatigue because the food can change while the plate logic stays the same.`]},{heading:`Choose Carbohydrates With Context`,subheading:`Portion and pairing matter`,paragraphs:[`Rice, roti, potatoes, oats, beans, and fruit can fit many diabetes plans when portions are intentional and paired with protein and fiber.`,`The question is not only what carbohydrate you eat, but how much, how often, and what surrounds it on the plate.`]},{heading:`Use Family Meals Strategically`,paragraphs:[`Separate diet food often fails because it isolates the client. A better approach is to adjust the shared meal: add salad, increase protein, reduce refined portions, and improve timing.`,`When the family meal supports the plan, consistency improves without extra cooking burden.`]},{heading:`Track Trends, Not Single Readings`,paragraphs:[`One glucose reading is information, not a verdict. Review patterns around breakfast, late dinners, stress, sleep, and walking after meals.`,`These trends help a nutritionist refine meal timing and food pairings with much more confidence.`]}],articleFaqs:[{id:`diabetes-friendly-plate-method-for-busy-families-faq-1`,question:`Can diabetic meal plans include rice, roti, or potatoes?`,answer:`Yes — these can fit many diabetes plans when portions are intentional and paired with protein and fiber. The key is how much and how often, not total avoidance.`},{id:`diabetes-friendly-plate-method-for-busy-families-faq-2`,question:`Do I need to cook separate meals for a family member with diabetes?`,answer:`No — adjusting the shared family meal (more salad, more protein, reduced refined portions, better timing) usually works better than isolating one person with separate diet food.`},{id:`diabetes-friendly-plate-method-for-busy-families-faq-3`,question:`Is one high blood sugar reading a sign the plan isn't working?`,answer:`One reading is information, not a verdict — reviewing patterns around breakfast, late dinners, stress, sleep, and post-meal walking gives a much clearer picture.`}],internalLinks:[{label:`Explore medical nutrition therapy`,to:`/services`},{label:`Book diabetes nutrition support`,to:`/booking`}]},{slug:`gut-health-meal-rhythm-for-bloating-relief`,title:`Gut Health Meal Rhythm for Bloating Relief`,seoTitle:`Gut Health Meal Rhythm for Bloating Relief`,seoDescription:`Use meal timing, fiber progression, hydration, and symptom tracking to support better digestion and reduce bloating with calm daily structure at home.`,category:`Diet Plans`,excerpt:`Gut health plans work better when fiber, timing, hydration, stress, and symptom tracking move together.`,publishedAt:`2026-04-09`,readTime:`7 min read`,heroImage:`https://images.unsplash.com/photo-1505253716362-afaea1d3d1af?auto=format&fit=crop&w=1200&q=80`,sections:[{heading:`Create a Predictable Meal Rhythm`,paragraphs:[`Irregular meals can make bloating harder to interpret. A consistent meal rhythm gives the gut clearer signals and makes symptom patterns easier to track.`,`Start by spacing meals in a way that prevents constant grazing while still avoiding extreme hunger.`]},{heading:`Increase Fiber Gradually`,subheading:`More is not always better at first`,paragraphs:[`Fiber is helpful, but sudden increases can worsen bloating. Add legumes, vegetables, seeds, and whole grains gradually while monitoring tolerance.`,`Hydration matters because fiber without enough fluid can increase discomfort.`]},{heading:`Identify Trigger Patterns`,paragraphs:[`Track symptoms alongside meal timing, stress, sleep, caffeine, dairy, legumes, cruciferous vegetables, and eating speed.`,`Patterns usually become clearer after two weeks of calm observation rather than one day of strict elimination.`]},{heading:`Know When to Get Support`,paragraphs:[`Persistent pain, unexplained weight loss, blood in stool, or severe symptoms should be discussed with a qualified medical professional.`,`Nutrition coaching can support day-to-day structure, but red-flag symptoms deserve clinical review.`]}],articleFaqs:[{id:`gut-health-meal-rhythm-for-bloating-relief-faq-1`,question:`Will eating more fiber immediately reduce bloating?`,answer:`Not necessarily — sudden fiber increases can worsen bloating, so legumes, vegetables, seeds, and whole grains should be added gradually while monitoring tolerance and hydration.`},{id:`gut-health-meal-rhythm-for-bloating-relief-faq-2`,question:`How long does it take to identify bloating triggers?`,answer:`Patterns usually become clearer after about two weeks of calm tracking of meals, stress, sleep, caffeine, dairy, and eating speed, rather than one day of strict elimination.`},{id:`gut-health-meal-rhythm-for-bloating-relief-faq-3`,question:`When should bloating be checked by a doctor instead of a nutritionist?`,answer:`Persistent pain, unexplained weight loss, blood in stool, or severe symptoms should be reviewed by a qualified medical professional — nutrition coaching supports day-to-day structure, not red-flag symptoms.`}],internalLinks:[{label:`See custom diet blueprint service`,to:`/services`},{label:`Ask about gut nutrition support`,to:`/contact`}]},{slug:`ramadan-nutrition-plan-for-energy-and-fat-loss`,title:`Ramadan Nutrition Plan for Energy and Fat Loss`,seoTitle:`Ramadan Nutrition Plan for Energy and Fat Loss`,seoDescription:`Build a balanced Ramadan nutrition plan for suhoor, iftar, hydration, energy, digestion, and sustainable fat-loss support without rebound cravings daily.`,category:`Weight Loss`,excerpt:`Fasting routines can support health goals when suhoor, iftar, hydration, and protein are planned with intention.`,publishedAt:`2026-02-08`,readTime:`8 min read`,heroImage:`https://images.unsplash.com/photo-1543352634-a1c51d9f1fa7?auto=format&fit=crop&w=1200&q=80`,sections:[{heading:`Build a Strong Suhoor`,paragraphs:[`Suhoor should focus on protein, slow carbohydrates, fiber, and hydration. This combination supports fullness and steadier energy through the fasting window.`,`Good options include eggs with roti and vegetables, Greek yogurt with oats and fruit, lentils with salad, or chicken with whole grains.`]},{heading:`Break the Fast Calmly`,subheading:`Avoid turning iftar into a rebound meal`,paragraphs:[`Start with water and a small portion, pause briefly, then build a balanced plate. This reduces overeating after long fasting hours.`,`Keep fried foods occasional rather than daily, especially if fat loss, digestion, or blood sugar stability is a goal.`]},{heading:`Hydrate Between Iftar and Sleep`,paragraphs:[`Hydration is easier when spread across the evening rather than forced all at once. Include water, soups, fruits, and mineral-rich foods.`,`Caffeine timing matters. Late tea or coffee can reduce sleep quality, which affects cravings and next-day energy.`]},{heading:`Protect Protein and Movement`,paragraphs:[`Protein often drops during Ramadan because meals become snack-heavy. Anchor both suhoor and iftar with a clear protein source.`,`Light walking after iftar can support digestion and glucose control without adding pressure during fasting hours.`]}],articleFaqs:[{id:`ramadan-nutrition-plan-for-energy-and-fat-loss-faq-1`,question:`What should suhoor include for steady energy during fasting?`,answer:`Protein, slow carbohydrates, fiber, and hydration — such as eggs with roti and vegetables, Greek yogurt with oats and fruit, or lentils with salad.`},{id:`ramadan-nutrition-plan-for-energy-and-fat-loss-faq-2`,question:`How can I avoid overeating at iftar?`,answer:`Start with water and a small portion, pause briefly, then build a balanced plate — this reduces the rebound-overeating pattern that long fasting hours can trigger.`},{id:`ramadan-nutrition-plan-for-energy-and-fat-loss-faq-3`,question:`Does Ramadan fasting make it harder to keep protein intake up?`,answer:`Protein intake often drops because meals become snack-heavy, so anchoring both suhoor and iftar with a clear protein source is important for maintaining fullness and muscle.`}],internalLinks:[{label:`Start a weight loss coaching plan`,to:`/services`},{label:`Book Ramadan nutrition consultation`,to:`/booking`}]},{slug:`heart-healthy-diet-plan-for-cholesterol-and-blood-pressure`,title:`Heart-Healthy Diet Plan for Cholesterol and Blood Pressure Control`,seoTitle:`Heart-Healthy Diet Plan Online | Dietrix Fit`,seoDescription:`Build a heart-healthy diet plan that lowers LDL cholesterol and blood pressure with fiber, healthy fats, sodium control, and sustainable meal structure.`,category:`Health Conditions`,excerpt:`Heart health improves through direction, not deprivation. Fiber, potassium, and the right fats do more than any single "superfood."`,publishedAt:`2026-05-14`,readTime:`8 min read`,heroImage:`https://images.unsplash.com/photo-1490645935967-10de6ba17061?auto=format&fit=crop&w=1200&q=80`,sections:[{heading:`Why Fiber and Sodium Are the Two Levers That Matter Most`,paragraphs:[`Soluble fiber from oats, beans, and lentils binds cholesterol in the digestive tract and helps lower LDL over 4 to 6 weeks of consistent intake. Aim for at least 25 to 30 grams of total fiber daily.`,`Sodium works the opposite way on blood pressure. Most excess sodium comes from packaged and restaurant food, not the salt shaker, so cooking more meals at home is usually the single biggest lever.`]},{heading:`Choose Fats That Work For Your Arteries`,subheading:`Not all fats affect cholesterol the same way`,paragraphs:[`Replace saturated fats — found in fried foods, fatty cuts of meat, and butter — with unsaturated sources like olive oil, nuts, seeds, and fatty fish.`,`Fatty fish such as salmon, mackerel, and sardines twice a week supply omega-3s that support healthy triglyceride levels.`]},{heading:`Build a Heart-Healthy Plate`,paragraphs:[`Fill half the plate with vegetables and fruit, a quarter with whole grains like oats, quinoa, or brown rice, and a quarter with lean protein or legumes, finished with a drizzle of olive oil.`,`This structure naturally raises potassium and fiber while lowering sodium and saturated fat, without needing to count every gram.`]},{heading:`Common Mistakes That Stall Progress`,paragraphs:[`"Low-fat" packaged snacks often replace fat with refined sugar and sodium, which can worsen triglycerides and blood pressure despite the label.`,`Skipping potassium-rich foods like bananas, potatoes, and leafy greens is a common oversight — potassium helps counter sodium's effect on blood pressure.`]},{heading:`What to Track Over Time`,paragraphs:[`Blood pressure readings, waist circumference, and lipid panel results (LDL, HDL, triglycerides) every 3 months give a clearer picture than daily weight alone.`,`Give any heart-healthy eating pattern at least 8 to 12 weeks before reassessing — cholesterol and blood pressure respond to consistency, not single meals.`]}],articleFaqs:[{id:`heart-healthy-diet-plan-for-cholesterol-and-blood-pressure-faq-1`,question:`What foods lower cholesterol fastest?`,answer:`Soluble fiber from oats, beans, and lentils binds cholesterol in the gut and can help lower LDL within 4 to 6 weeks of consistently eating 25 to 30 grams of total fiber daily.`},{id:`heart-healthy-diet-plan-for-cholesterol-and-blood-pressure-faq-2`,question:`Does cutting salt really lower blood pressure?`,answer:`Yes — most excess sodium comes from packaged and restaurant food rather than the salt shaker, so cooking more meals at home is usually the biggest single lever for blood pressure.`},{id:`heart-healthy-diet-plan-for-cholesterol-and-blood-pressure-faq-3`,question:`How often should I eat fish for heart health?`,answer:`Aim for fatty fish like salmon, mackerel, or sardines twice a week to supply omega-3s that support healthy triglyceride levels.`}],internalLinks:[{label:`Explore heart-healthy nutrition coaching`,to:`/services`},{label:`Book a heart-health consultation`,to:`/booking`}]},{slug:`thyroid-friendly-nutrition-for-hypothyroidism`,title:`Thyroid-Friendly Nutrition: What to Eat for Hypothyroidism`,seoTitle:`Thyroid-Friendly Diet Plan | Dietrix Fit`,seoDescription:`Learn thyroid-friendly nutrition for hypothyroidism — iodine, selenium, and iron-aware meal planning, medication timing, and foods that support energy.`,category:`Health Conditions`,excerpt:`Thyroid nutrition works best as steady support around your treatment, not a replacement for it. Timing and specific nutrients matter more than any food to avoid.`,publishedAt:`2026-06-22`,readTime:`8 min read`,heroImage:`https://images.unsplash.com/photo-1498837167922-ddd27525d352?auto=format&fit=crop&w=1200&q=80`,sections:[{heading:`Nutrition Supports Your Treatment, It Does Not Replace It`,paragraphs:[`If you take thyroid medication, food and supplement timing matters more than any specific ingredient. Take levothyroxine on an empty stomach and wait 30 to 60 minutes before eating or drinking coffee.`,`Calcium, iron, and high-fiber supplements taken too close to your dose can reduce absorption — space them at least 4 hours apart.`]},{heading:`Nutrients That Matter Most`,subheading:`Iodine, selenium, iron, and zinc`,paragraphs:[`Iodine and selenium support thyroid hormone production. Iodized salt, dairy, eggs, and seafood cover most needs without extra supplementation for most people.`,`Iron deficiency is common alongside hypothyroidism and can worsen fatigue. Pair iron-rich foods like lean red meat or lentils with vitamin C sources to improve absorption.`]},{heading:`Foods That Get Unfairly Blamed`,paragraphs:[`Raw cruciferous vegetables like broccoli and cabbage contain compounds that can interfere with iodine uptake in very large, raw quantities — but cooking largely deactivates this effect, so normal servings of cooked vegetables are not a concern.`,`Gluten-free eating only helps thyroid symptoms if you also have celiac disease or a diagnosed gluten sensitivity. Cutting it without a reason adds restriction without benefit.`]},{heading:`Eating for Energy and Metabolism`,paragraphs:[`Hypothyroidism can slow metabolism and increase fatigue, so protein at each meal and consistent meal timing help stabilize energy better than skipping meals to compensate.`,`Strength training two to three times weekly supports the muscle mass that hypothyroidism can gradually reduce, complementing nutrition rather than replacing it.`]},{heading:`What to Track With Your Doctor`,paragraphs:[`TSH, free T4, and sometimes free T3 lab values guide medication dosing — nutrition changes should be reviewed alongside these results, not instead of them.`,`Track energy, weight trend, hair and skin changes, and digestion over 8 to 12 week windows to see whether nutrition adjustments are helping.`]}],articleFaqs:[{id:`thyroid-friendly-nutrition-for-hypothyroidism-faq-1`,question:`When should I eat after taking thyroid medication?`,answer:`Wait 30 to 60 minutes after levothyroxine before eating or drinking coffee, and space calcium, iron, or high-fiber supplements at least 4 hours from your dose to protect absorption.`},{id:`thyroid-friendly-nutrition-for-hypothyroidism-faq-2`,question:`Do I need to avoid broccoli and cabbage with hypothyroidism?`,answer:`No — the compounds in cruciferous vegetables that affect iodine uptake are largely deactivated by cooking, so normal cooked servings are not a concern for most people.`},{id:`thyroid-friendly-nutrition-for-hypothyroidism-faq-3`,question:`Should I go gluten-free for my thyroid?`,answer:`Only if you also have celiac disease or a diagnosed gluten sensitivity — without one of those, cutting gluten adds restriction without a proven thyroid benefit.`}],internalLinks:[{label:`See our thyroid-aware nutrition coaching`,to:`/services`},{label:`Talk to our nutritionist about your labs`,to:`/contact`}]},{slug:`sports-nutrition-basics-for-strength-training-and-recovery`,title:`Sports Nutrition Basics for Strength Training and Recovery`,seoTitle:`Sports Nutrition Coaching Online | Dietrix Fit`,seoDescription:`Sports nutrition basics for strength training — protein targets, pre and post-workout meals, hydration, and recovery nutrition that actually moves the needle.`,category:`Diet Plans`,excerpt:`Performance nutrition is mostly about daily protein and consistent fueling. Pre-workout snacks and supplements matter far less than most people assume.`,publishedAt:`2026-07-30`,readTime:`7 min read`,heroImage:`https://images.unsplash.com/photo-1505253716362-afaea1d3d1af?auto=format&fit=crop&w=1200&q=80`,sections:[{heading:`Total Daily Protein Beats Perfect Timing`,paragraphs:[`For strength training, aim for 1.6 to 2.2 grams of protein per kilogram of bodyweight spread across 3 to 4 meals — this range consistently supports muscle repair and growth better than any single "anabolic window" strategy.`,`Hitting your daily protein target matters far more than eating it within 30 minutes of training, despite what most supplement marketing implies.`]},{heading:`What to Eat Before Training`,subheading:`Fuel without stomach discomfort`,paragraphs:[`A meal with carbohydrate and moderate protein 2 to 3 hours before training gives steady energy without digestive discomfort — think rice with chicken, or oats with yogurt.`,`If training soon after waking, a smaller carbohydrate-forward snack like a banana or toast is usually easier to tolerate than a full meal.`]},{heading:`Recovery Nutrition That Actually Helps`,paragraphs:[`Within 1 to 2 hours after training, a meal combining protein and carbohydrate — such as a protein shake with fruit, or eggs with toast — replenishes glycogen and supports muscle repair.`,`Sleep and total daily calories affect recovery more than the exact post-workout meal, so consistent sleep and adequate energy intake should come first.`]},{heading:`Hydration and Electrolytes`,paragraphs:[`Losing more than 2 percent of bodyweight in sweat during training measurably reduces performance — weighing yourself before and after a session once is enough to estimate your typical sweat loss.`,`For sessions under 60 minutes, water is usually enough; longer or hotter sessions benefit from adding sodium and electrolytes.`]},{heading:`Do You Need Supplements?`,paragraphs:[`Creatine monohydrate (3 to 5 grams daily) and a protein supplement to close daily protein gaps are the two most evidence-backed additions — everything else is optional on top of a solid food-first plan.`,`No supplement compensates for inconsistent training, inadequate sleep, or a protein-deficient diet, so build the fundamentals first.`]}],articleFaqs:[{id:`sports-nutrition-basics-for-strength-training-and-recovery-faq-1`,question:`How much protein do I need for strength training?`,answer:`Aim for 1.6 to 2.2 grams of protein per kilogram of bodyweight daily, spread across 3 to 4 meals — this supports muscle repair better than timing protein around a narrow post-workout window.`},{id:`sports-nutrition-basics-for-strength-training-and-recovery-faq-2`,question:`What should I eat before a workout?`,answer:`A meal with carbohydrate and moderate protein 2 to 3 hours before training, like rice with chicken or oats with yogurt, provides steady energy without digestive discomfort.`},{id:`sports-nutrition-basics-for-strength-training-and-recovery-faq-3`,question:`Are supplements necessary for muscle growth?`,answer:`Creatine monohydrate and a protein supplement to close daily protein gaps are the most evidence-backed options, but no supplement replaces consistent training, sleep, and a protein-adequate diet.`}],internalLinks:[{label:`Explore performance nutrition coaching`,to:`/services`},{label:`Book a sports nutrition consultation`,to:`/booking`}]},{slug:`plant-based-weight-loss-meal-plan-for-beginners`,title:`Plant-Based Weight Loss: A Practical Meal Plan for Beginners`,seoTitle:`Plant-Based Weight Loss Plan | Dietrix Fit`,seoDescription:`A practical plant-based weight loss meal plan for beginners covering protein sources, meal structure, and common mistakes that stall fat loss.`,category:`Weight Loss`,excerpt:`Plant-based weight loss fails most often from too little protein, not too many carbs. Fix the protein gap first and the rest gets easier.`,publishedAt:`2026-09-05`,readTime:`7 min read`,heroImage:`https://images.unsplash.com/photo-1467453678174-768ec283a940?auto=format&fit=crop&w=1200&q=80`,sections:[{heading:`Solve the Protein Gap First`,paragraphs:[`Most plant-based diets fall short on protein, not calories. Tofu, tempeh, lentils, chickpeas, edamame, and seitan all deliver 15 to 20 grams of protein per serving and should anchor every meal.`,`Aim for at least 1.2 to 1.6 grams of protein per kilogram of bodyweight daily during a fat-loss phase, split across three or four plant-protein-forward meals.`]},{heading:`Build a Plate That Actually Fills You Up`,subheading:`Volume and fiber do the heavy lifting`,paragraphs:[`Combine a plant protein, a high-fiber vegetable, a whole grain or starchy vegetable, and a small amount of fat like avocado, nuts, or tahini — this combination slows digestion and extends fullness.`,`Legumes and whole grains together also form complete protein profiles, so variety across the week matters more than any single "perfect" ingredient.`]},{heading:`Avoid the Ultra-Processed Trap`,paragraphs:[`Plant-based does not automatically mean lower-calorie — vegan burgers, dairy-free desserts, and meat substitutes are often highly processed and calorie-dense.`,`Read labels for added oils and sugar; whole-food plant proteins are usually more filling per calorie than their processed alternatives.`]},{heading:`Micronutrients Worth Watching`,paragraphs:[`Vitamin B12, iron, zinc, calcium, and omega-3s need deliberate planning on a fully plant-based diet — a B12 supplement is considered necessary for anyone eating no animal products.`,`Pair iron-rich plant foods like lentils and spinach with vitamin C sources such as citrus or peppers to improve absorption.`]},{heading:`A Sample Day to Start With`,paragraphs:[`Breakfast: tofu scramble with vegetables and whole-grain toast. Lunch: lentil and quinoa bowl with roasted vegetables and tahini. Dinner: chickpea curry with brown rice and a side salad.`,`Repeat simple templates like this for 2 to 3 weeks before adjusting — consistency reveals what is actually working better than frequent recipe changes.`]}],articleFaqs:[{id:`plant-based-weight-loss-meal-plan-for-beginners-faq-1`,question:`Can you lose weight on a plant-based diet without eating meat?`,answer:`Yes — the key is closing the protein gap with tofu, tempeh, lentils, chickpeas, and edamame, aiming for 1.2 to 1.6 grams of protein per kilogram of bodyweight daily.`},{id:`plant-based-weight-loss-meal-plan-for-beginners-faq-2`,question:`Is plant-based food automatically lower calorie?`,answer:`No — vegan burgers, dairy-free desserts, and many meat substitutes are often highly processed and calorie-dense, so whole-food plant proteins are usually the better choice for fat loss.`},{id:`plant-based-weight-loss-meal-plan-for-beginners-faq-3`,question:`What nutrients should I watch on a plant-based diet?`,answer:`Vitamin B12, iron, zinc, calcium, and omega-3s need deliberate planning — a B12 supplement is considered necessary for anyone eating no animal products.`}],internalLinks:[{label:`Start a plant-based weight loss plan`,to:`/services`},{label:`Book a plant-based nutrition consultation`,to:`/booking`}]}],g=[{cluster:`Weight loss`,pillar:`/services`,supportingArticles:[`Safe weight loss diet plan for beginners`,`High protein breakfast ideas for fat loss`,`How to stop evening cravings without crash dieting`,`Calorie deficit mistakes that slow progress`,`Weight loss meal prep for office workers`,`Ramadan nutrition plan for fat loss`,`Best diet plan for working women at home`,`How to lose weight fast safely with a nutritionist`]},{cluster:`Women health`,pillar:`/blog/pcos-diet-plan-basics-that-actually-work`,supportingArticles:[`PCOS diet plan basics for hormonal balance`,`Insulin resistance meal plan for PCOS`,`Best breakfast for PCOS cravings`,`Anti-inflammatory foods for women with PCOS`,`PCOS weight loss without extreme dieting`,`Cycle tracking and nutrition for hormonal health`,`Thyroid friendly diet routine for busy women`,`Gut health and hormones nutrition guide`]},{cluster:`Fitness nutrition`,pillar:`/services`,supportingArticles:[`Fitness nutrition basics for beginners`,`Pre-workout meal ideas for fat loss`,`Post-workout protein meals for women`,`How much protein do you need daily`,`Strength training nutrition for weight loss`,`Simple muscle gain diet plan at home`,`Hydration and electrolytes for active adults`,`Healthy snacks for workouts and office days`]},{cluster:`Meal planning`,pillar:`/blog/simple-weekly-diet-planning-for-busy-professionals`,supportingArticles:[`Simple weekly diet planning framework`,`Affordable grocery list for healthy eating`,`Family meal planning for weight loss`,`Diabetes friendly family dinner ideas`,`Healthy lunch ideas for remote workers`,`Meal planning for night shift workers`,`How to build a balanced plate`,`Diet plan for people who hate cooking`]},{cluster:`Pakistan nutrition`,pillar:`/services`,supportingArticles:[`Online nutritionist Pakistan: how remote diet coaching works`,`Pakistani diet plan for weight loss with roti and rice`,`PCOS diet plan Pakistan for busy women`,`Diabetes meal plan Pakistan for family meals`,`Healthy Pakistani breakfast ideas for fat loss`,`Affordable custom diet plan Pakistan`,`Ramadan nutrition plan for Pakistan clients`,`South Asian portions for biryani, roti, rice, and curry`]},{cluster:`International online nutrition`,pillar:`/booking`,supportingArticles:[`Online nutritionist USA: remote diet coaching for busy clients`,`Online nutritionist UK and England: custom meal planning from home`,`Online nutritionist Canada: weight loss and PCOS diet support`,`Online nutritionist Germany for English-speaking clients`,`Online nutritionist France for custom diet plans`,`Online nutritionist KSA and Saudi Arabia meal planning`,`Online nutritionist Dubai and UAE weight loss coaching`,`Online nutritionist Australia for remote diet plans`]}],_=[{id:`seo-faq-1`,question:`How does online nutrition consultation work?`,answer:`Online nutrition consultation starts with your health goals, food routine, medical context, lifestyle, and preferences. A nutritionist then builds a personalized plan and adjusts it through check-ins.`},{id:`seo-faq-2`,question:`What is the best diet for weight loss?`,answer:`The best diet for weight loss is a sustainable plan that creates a moderate calorie deficit, keeps protein and fiber high, controls cravings, and matches your normal meals and schedule.`},{id:`seo-faq-3`,question:`Can I get a custom diet plan for PCOS online?`,answer:`Yes. A custom PCOS diet plan can be delivered online using insulin-aware meal structure, protein and fiber targets, symptom tracking, and lifestyle adjustments.`},{id:`seo-faq-4`,question:`Do online diet plans work for diabetes?`,answer:`Online diet plans can support diabetes when meals are built around controlled carbohydrates, protein, fiber, meal timing, glucose trends, and medical guidance where needed.`},{id:`seo-faq-5`,question:`Is Dietrix Fit available internationally?`,answer:`Yes. Dietrix Fit is remote-first and supports clients worldwide through online consultations, personalized diet plans, progress reviews, and digital communication.`},{id:`seo-faq-6`,question:`What should I expect from a personalized diet plan?`,answer:`A personalized diet plan should include meal structure, portion guidance, food swaps, grocery direction, lifestyle targets, progress tracking, and adjustments based on your results.`},{id:`seo-faq-7`,question:`Can clients in Pakistan book Dietrix Fit online?`,answer:`Yes. Clients in Pakistan can book Dietrix Fit online for weight loss, PCOS, diabetes, gut health, fitness nutrition, and custom diet plans built around Pakistani meals and routines.`},{id:`seo-faq-8`,question:`Can a Pakistani diet plan include roti, rice, curry, and biryani?`,answer:`Yes. A Pakistani diet plan can include roti, rice, curry, biryani, lentils, yogurt, and family meals when portions, protein, fiber, meal timing, and weekly consistency are planned carefully.`},{id:`seo-faq-9`,question:`Can clients in the UK, England, USA, Canada, Australia, Germany, or France book Dietrix Fit?`,answer:`Yes. Dietrix Fit supports international clients in the UK, England, USA, Canada, Australia, Germany, and France through online consultations, custom diet plans, and remote progress reviews.`},{id:`seo-faq-10`,question:`Can clients in KSA, Saudi Arabia, Dubai, or the UAE book an online diet plan?`,answer:`Yes. Clients in KSA, Saudi Arabia, Dubai, and the UAE can book online nutrition consultations for weight loss, PCOS, diabetes, family meal planning, and custom diet support.`}];function v(o=u){return{"@context":`https://schema.org`,"@type":`MedicalBusiness`,"@id":`${t}/#organization`,name:a,url:t,logo:n(`/brand/dietrix-fit-organization-logo-512.png`),image:n(`/brand/dietrix-fit-organization-logo-512.png`),email:e,priceRange:`$50`,description:`Evidence-based online nutrition coaching for weight loss, PCOS, diabetes, gut health, and performance, serving clients globally.`,founder:{"@type":`Person`,"@id":`${t}/#rimsha-naseer`,name:i,jobTitle:`Certified Clinical Nutritionist`,url:n(`/about`)},medicalSpecialty:[`Nutrition`,`Dietitian`,`Weight Loss`],areaServed:[`Worldwide`,...r.map(e=>e.country)],availableService:o.map(e=>({"@type":`Service`,name:e.title,description:e.summary,offers:{"@type":`Offer`,price:e.priceFrom.replace(`$`,``),priceCurrency:`USD`}})),sameAs:[]}}function y(){return{"@context":`https://schema.org`,"@type":`Person`,"@id":`${t}/#rimsha-naseer`,name:i,jobTitle:`Certified Clinical Nutritionist`,image:n(`/brand/dietrix-fit-organization-logo-512.png`),email:e,worksFor:{"@id":`${t}/#organization`},url:n(`/about`),knowsAbout:[`Weight loss nutrition`,`PCOS diet plans`,`Diabetes meal planning`,`Fitness nutrition`,`Gut health nutrition`,`Online nutrition consultation`,`Pakistani diet plans`,`South Asian nutrition`,`International online nutrition coaching`,`Remote diet plans for USA, UK, Canada, Europe, Middle East, and Australia`],hasCredential:s.map(e=>({"@type":`EducationalOccupationalCredential`,name:e}))}}function b(){return{"@context":`https://schema.org`,"@type":`WebSite`,"@id":`${t}/#website`,name:a,url:t,publisher:{"@id":`${t}/#organization`},potentialAction:{"@type":`SearchAction`,target:`${t}/blog?q={search_term_string}`,"query-input":`required name=search_term_string`}}}function x(e){return{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:e.map(e=>({"@type":`Question`,name:e.question,acceptedAnswer:{"@type":`Answer`,text:e.answer}}))}}function S(e){return{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:e.map((e,t)=>({"@type":`ListItem`,position:t+1,name:e.name,item:n(e.path)}))}}function C(e){return{"@context":`https://schema.org`,"@type":`Article`,mainEntityOfPage:n(`/blog/${e.slug}`),headline:e.title,description:e.seoDescription,datePublished:e.publishedAt,dateModified:e.updatedAt??e.publishedAt,articleSection:e.category,image:e.heroImage,author:{"@id":`${t}/#rimsha-naseer`},publisher:{"@id":`${t}/#organization`}}}export{f as _,y as a,_ as c,m as d,o as f,p as g,l as h,v as i,h as l,u as m,S as n,b as o,d as p,x as r,g as s,C as t,s as u,c as v};